\end{definition}

\begin{lemma}[Projectivity and completeness of the dot-product operators]\label{lem:tau-dot-product-projective}
	\lean{MIPStarRE.QPBT.tauDotProj_isProj, MIPStarRE.QPBT.sum_tauDotProj_eq_one}
