	$\{\tau^W_a(\tilde{u})\}_{a\in\F_q}$ is a projective measurement.
\end{lemma}

\begin{definition}[Pulled-apart Pauli basis measurements]\label{def:tilde-m-measurement}
	\lean{MIPStarRE.QPBT.tildeM}
